INSERT INTO `mindbody_cutoverstep` VALUES (1,'2026-09-29 17:23:12.111791','2026-09-29 17:23:12.111818',1,1,'Trial import into the test copy; team checks member counts, expiries and stock against Mindbody','استيراد تجريبي ومراجعة الأعداد وتواريخ الانتهاء والمخزون مقابل مايندبودي',NULL,'',NULL,NULL,NULL),(2,'2026-09-29 17:23:12.111859','2026-09-29 17:23:12.111870',1,2,'Every Mindbody pricing option mapped or skipped','ربط كل خيارات الأسعار من مايندبودي أو استبعادها',NULL,'',NULL,NULL,NULL),(3,'2026-09-29 17:23:12.111897','2026-09-29 17:23:12.111908',1,3,'Parallel run: weekly sales and active members agree (or differences explained) at both branches','التشغيل المتوازي: تطابق المبيعات والأعضاء النشطين أسبوعياً في الفرعين',NULL,'',NULL,NULL,NULL),(4,'2026-09-29 17:23:12.111925','2026-09-29 17:23:12.115600',1,4,'Staff trained: 15-minute walkthrough per role','تدريب الموظفين: جولة 15 دقيقة لكل دور','2026-09-27 17:23:12.117507','Walkthroughs held at both branches (test).',NULL,2,2),(5,'2026-09-29 17:23:12.111945','2026-09-29 17:23:12.111951',1,5,'Freeze Mindbody entries (no new sales or check-ins there)','إيقاف الإدخال في مايندبودي',NULL,'',NULL,NULL,NULL),(6,'2026-09-29 17:23:12.111968','2026-09-29 17:23:12.111974',1,6,'Final import of the delta (same files, same screen)','الاستيراد النهائي للفروقات',NULL,'',NULL,NULL,NULL),(7,'2026-09-29 17:23:12.111990','2026-09-29 17:23:12.111996',1,7,'Monthly count at both branches to confirm the stock baseline','جرد شهري في الفرعين لتأكيد المخزون',NULL,'',NULL,NULL,NULL),(8,'2026-09-29 17:23:12.112011','2026-09-29 17:23:12.112017',1,8,'Front desks switched to the new desk; card terminals and receipts checked','تحويل الاستقبال إلى النظام الجديد ومراجعة أجهزة الدفع والإيصالات',NULL,'',NULL,NULL,NULL),(9,'2026-09-29 17:23:12.112031','2026-09-29 17:23:12.112037',1,9,'Website booking and schedule pointing at the system','ربط الحجز والجدول في الموقع بالنظام',NULL,'',NULL,NULL,NULL),(10,'2026-09-29 17:23:12.112052','2026-09-29 17:23:12.11205