  `rank_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `one_rank_per_member_art` (`member_id`,`art_id`),
  KEY `training_memberrank_art_id_ef42a32c_fk_training_art_id` (`art_id`),
  KEY `training_memberrank_created_by_id_ef8fb4a0_fk_accounts_user_id` (`created_by_id`),
