  CONSTRAINT `training_memberrank_art_id_ef42a32c_fk_training_art_id` FOREIGN KEY (`art_id`) REFERENCES `training_art` (`id`),
  CONSTRAINT `training_memberrank_created_by_id_ef8fb4a0_fk_accounts_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `accounts_user` (`id`),
