  CONSTRAINT `training_memberrank_updated_by_id_7cc70e78_fk_accounts_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `accounts_user` (`id`),
  CONSTRAINT `training_memberrank_chk_1` CHECK ((`version` >= 0))
